INSERT INTO `muscle_group` (`mug_id`, `mug_image`, `mug_name`, `mug_zone`) VALUES (1,'uploads/muscle_groups/Chest.jpg','อก',1),(2,'uploads/muscle_groups/Back.jpg','หลัง',1),(3,'uploads/muscle_groups/Shoulders.jpg','ไหล่',1),(4,'uploads/muscle_groups/Biceps.jpg','หน้าแขน',1),(5,'uploads/muscle_groups/Triceps.jpg','หลังแขน',1),(6,'uploads/muscle_groups/forearms.jpg','ท่อนแขน',1),(7,'uploads/muscle_groups/Thighs.jpg','ขา',2),(8,'uploads/muscle_groups/glutes.jpg','ก้นและหลังขา',2),(9,'uploads/muscle_groups/core.jpg','หน้าท้องและแกนกลาง',3);
