INSERT INTO `cardio_category` (`cdc_id`, `cdc_image`, `cdc_name`, `cdc_description`) VALUES (1,'uploads/cardio_categories/1788151203025116500.jpg','เครื่องยิม','ความเข้มข้นต่ำต่อเนื่อง รักษาอัตราการเต้นหัวใจคงที่ เน้นเบิร์นไขมัน ไม่กินกล้ามเนื้อ'),(2,'uploads/cardio_categories/1788151196610994000.jpg','กีฬาและกิจกรรม','ความเข้มข้นปานกลาง เพิ่มความอึดของปอดและหัวใจ');
