INSERT INTO `cardio` (`cdo_id`, `cdo_image`, `cdo_name`, `cdo_mets`, `cdo_has_distance`, `cdo_description`, `cdo_technique`, `cdo_video`, `cdo_loop_video`, `cdc_id`) VALUES (1,'uploads/cardio/images/incline_treadmill.jpg','เดินชันบนสายพาน',8.80,1,'การเดินบนลู่วิ่งโดยปรับความชันระดับสูงเพื่อเพิ่มการเผาผลาญ เป็นท่าคาร์ดิโอยอดฮิตที่ช่วยรักษาพลังงานและเซฟข้อเข่าสำหรับสายเวท','ตั้งค่าความชันลู่วิ่ง (Incline) ไปที่ระดับ 8-12% และความเร็ว (Speed) ที่ 4-5 กม./ชม. ยืนตรงกึ่งกลางสายพาน\r\nเดินด้วยจังหวะที่สม่ำเสมอ ลงส้นเท้าแล้วถ่ายน้ำหนักไปที่ปลายเท้า ปล่อยแขนแกว่งตามธรรมชาติโดยไม่จับราวบาร์ประคองเพื่อเกลี่ยแรงให้แกนกลางทำงาน\r\nห้ามจับราวบาร์ประคองเดิน (ยกเว้นตอนเสียหลัก) และอย่าใช้ความเร็วสูงเกินไปจนต้องเปลี่ยนเป็นวิ่ง','uploads/cardio/video/incline_treadmill_loop.mp4','uploads/cardio/videoloop/incline_treadmill_loop.mp4',1),(2,'uploads/cardio/images/stair_climber.jpg','เครื่องก้าวบันได',9.30,0,'การเดินขึ้นบันไดจำลองอยู่กับที่เพื่อเผาผลาญแคลอรีระดับสูง พร้อมกระตุ้นกล้ามเนื้อก้นและต้นขาไปในตัว','ยืนบนเครื่องก้าวบันได ตั้งระดับความเร็วเริ่มต้นในระดับต่ำถึงปานกลาง มือวางแตะราวบาร์จับเบาๆ เพื่อพยุงบาลานซ์\r\nก้าวเหยียบฝ่าเท้าลงบนขั้นบันไดให้เต็มเท้าสลับซ้ายขวา ยืดอก หลังตรง เกร็งหน้าท้องเบาๆ ตลอดการก้าวเพื่อส่งแรงจากก้น\r\nห้ามเขย่งส้นเท้าก้าวเด็ดขาดเพื่อเซฟข้อเข่า และห้ามทิ้งน้ำหนักตัวทั้งหมดหนีบลงบนราวบาร์จับ','uploads/cardio/video/incline_treadmill_loop.mp4','uploads/cardio/videoloop/stair_climber_loop.mp4',1),(3,'uploads/cardio/images/stationary_cycling.jpg','ปั่นจักรยานฟิตเนส',6.80,1,'การปั่นจักรยานอยู่กับที่เพื่อคาร์ดิโอแรงกระแทกต่ำ เหมาะอย่างยิ่งสำหรับการฟื้นฟูกล้ามเนื้อขาและข้อต่อในวันพัก','ปรับระดับเบาะนั่งให้สูงพอดี (เมื่อเหยียดขาปั่นลงสุด เข่าควรงอเล็กน้อย 10-15 องศา) นั่งหลังตรง จับแฮนด์ให้กระชับ\r\nออกแรงปั่นจักรยานด้วยความเร็วรอบ (RPM) ที่สม่ำเสมอ ปรับแรงต้านให้รู้สึกตึงขาปานกลาง เกร็งหน้าท้องพยุงแนวหลัง\r\nห้ามปล่อยให้หัวเข่าเหยียดตึงเป๊ะตอนปั่นลงสุด และรักษาแนวหลังให้ตรง ไม่นั่งก้มตัวห่อไหล่','uploads/cardio/video/incline_treadmill_loop.mp4','uploads/cardio/videoloop/stationary_cycling_loop.mp4',1),(4,'uploads/cardio/images/rowing_machine.jpg','เครื่องกรรเชียงบก',7.50,1,'การออกกำลังกายเลียนแบบพายเรือบกที่ผสานคาร์ดิโอเข้ากับการฝึกกล้ามเนื้อแผ่นหลังและแกนกลางลำตัวอย่างสมบูรณ์แบบ','นั่งบนเบาะ รัดสายคาดเท้าให้แน่น มือจับด้ามจับในท่ายืดแขนตึง หลังตรง เข่างอพับเข้าหาเครื่อง\r\nออกแรงถีบขาไปข้างหลัง 60% เอนลำตัวพยุง 20% แล้วใช้หลังและแขนดึงด้ามจับเข้าหาลิ้นปี่อีก 20% ตอนกลับให้ยืดแขนออกก่อนแล้วจึงงอเข่าสไลด์กลับ\r\nห้ามงอหลังค่อมขณะออกแรงดึงเด็ดขาด และควบคุมจังหวะไม่ให้สายเคเบิลกระชากตัวกลับเร็วเกินไป','uploads/cardio/video/incline_treadmill_loop.mp4','',1),(5,'uploads/cardio/images/battle_ropes.jpg','สะบัดเชือกหนา',7.50,0,'คาร์ดิโอความเข้มข้นสูงในรูปแบบ Workout Finisher ที่ช่วยระเบิดไขมันสะสมและเพิ่มความอึดให้กล้ามเนื้อท่อนบน','ยืนแยกขากว้างเท่าหัวไหล่ ย่อตัวลงเล็กน้อยในท่าเตรียมพร้อม (Athletic Stance) จับปลายเชือกสองข้างให้แน่น ยืดอกขึ้น\nเกร็งแกนกลางลำตัวให้แน่น ออกแรงสะบัดเชือกขึ้น-ลงสลับซ้ายขวาอย่างรวดเร็วและต่อเนื่อง โดยใช้แรงส่งหลักจากหัวไหล่และแขน\nรักษาลำตัวส่วนล่างให้อยู่นิ่ง ห้ามโยกตัวหรือเด้งเอวขึ้นลงไปตามแรงสะบัดของเชือก','','',2),(6,'uploads/cardio/images/jump_rope.jpg','กระโดดเชือก',12.30,0,'กิจกรรมเผาผลาญพลังงานสูงที่ใช้อุปกรณ์น้อย ใช้พื้นที่จำกัด ช่วยเพิ่มความคล่องตัวและการทำงานประสานกันของร่างกาย','ยืนตรง เท้าชิดกัน มือสองข้างจับด้ามเชือกไว้ข้างลำตัว หนีบข้อศอกเข้าใกล้ลำตัว ปล่อยสายเชือกอยู่ด้านหลังเท้า\nแกว่งเชือกข้ามศีรษะโดยใช้การหมุนจากข้อข้อมือเท่านั้น กระโดดขึ้นจากพื้นเล็กน้อยพอให้เช็กรอดผ่าน ปล่อยตัวลงด้วยปลายเท้า\nห้ามกระโดดสูงเกินไป และต้องงอเข่าซับแรงกระแทกเบาๆ ทุกครั้ง ห้ามลงน้ำหนักเต็มส้นเท้าเด็ดขาด','https://youtube.com/shorts/Gx7xaFjW_Nc?si=fh4htTWiE1sFjFGe','uploads/cardio/videoloop/jump_rope_loop.mp4',2),(7,'uploads/cardio/images/bodyweight_hiit.jpg','HIIT บอดี้เวท',11.00,0,'การออกกำลังกายหนักสลับเบาด้วยท่าไร้อุปกรณ์เพื่อเร่งอัตราการเต้นของหัวใจและเบิร์นไขมันอย่างรวดเร็วในเวลาสั้น','เตรียมพื้นที่ว่างรอบตัวให้พร้อม ยืนในท่าตรง จัดตั้งระบบจับเวลา (เช่น ทำเต็มสปีด 45 วินาที พัก 15 วินาที)\nทำท่าบอดี้เวทความถี่สูง (เช่น Burpees, Mountain Climbers, Jumping Jacks) สลับกันด้วยความเร็วสูงสุดเท่าที่ทำได้ในเวลาที่กำหนด\nแม้ร่างกายจะเริ่มเหนื่อยล้าสะสม แต่ต้องรักษาความถูกต้องของฟอร์มท่าทางเอาไว้เพื่อป้องกันการบาดเจ็บข้อต่อ','','uploads/cardio/videoloop/bodyweight_hiit_loop.mp4',2),(8,'uploads/cardio/images/boxing_muay_thai.jpg','มวยไทย',10.30,0,'การคาร์ดิโอแนวสปอร์ตยอดนิยมที่ได้ฝึกความแข็งแรง ความยืดหยุ่น และการระเบิดพลังของกล้ามเนื้อผ่านการออกอาวุธ','ยืนจัดระเบียบร่างกายในท่าตั้งการ์ดคุมมวย (Fight Stance) เท้าแยกมั่นคง มือสองข้างยกขึ้นบังแนวใบหน้า\nออกอาวุธ (หมัด เท้า เข่า ศอก) ใส่กระสอบทรายหรืออากาศ โดยบิดสะโพกและแกนกลางลำตัวเพื่อส่งแรง หายใจออกเสียงดังทุกครั้งที่ออกอาวุธ\nระวังอย่าล็อกข้อศอกหรือข้อเข่าตึงเป๊ะตอนออกอาวุธสุดแรง เพราะจะทำให้ข้อต่อสะท้อนแรงกลับจนบาดเจ็บ','','uploads/cardio/videoloop/boxing_muay_thai_loop.mp4',2),(9,'uploads/cardio/images/swimming.jpg','ว่ายน้ำ',6.00,1,'คาร์ดิโอไร้แรงกระแทกที่ยอดเยี่ยมที่สุดสำหรับการเซฟข้อต่อ และช่วยผ่อนคลายกล้ามเนื้อที่ตึงล้าจากการยกเวท','สวมอุปกรณ์ว่ายน้ำให้พร้อม ก้าวลงสระแล้วจัดระเบียบร่างกายให้ลอยตัวขนานเรียบกับผิวน้ำ\r\nออกสตาร์ทว่ายน้ำด้วยท่าที่ถนัด ควบคุมการเตะขาและวาดแขนสลับซ้ายขวาอย่างเป็นจังหวะ หายใจเข้าทางปากและผ่อนออกทางจมูกในน้ำสม่ำเสมอ\r\nอย่ากลั้นหายใจนานเกินไปขณะว่ายน้ำ และระวังการเป็นตะคริวหากอบอุ่นร่างกายไม่เพียงพอก่อนลงสระ','uploads/cardio/video/incline_treadmill_loop.mp4','uploads/cardio/videoloop/swimming_loop.mp4',2),(10,'uploads/cardio/images/boxing_training.jpg','ชกมวย (ซ้อม)',7.80,0,'การซ้อมมวยสากลด้วยการชกกระสอบทรายหรือชกลม (Shadow Boxing) ช่วยฝึกความอึด ความเร็วของหมัด และการทำงานประสานกันของแขน ไหล่ และแกนกลางลำตัว','ยืนตั้งการ์ดในท่ามวยสากล เท้าแยกมั่นคง ย่อเข่าเล็กน้อย มือสองข้างยกขึ้นบังแนวใบหน้า\nออกหมัดตรง หมัดฮุก และหมัดอัปเปอร์คัตใส่กระสอบทรายหรืออากาศ โดยบิดสะโพกและลำตัวส่งแรงจากเท้าขึ้นมาที่หมัด หายใจออกทุกครั้งที่ออกหมัด\nระวังอย่าล็อกข้อศอกตึงเป๊ะตอนปล่อยหมัดสุดแรง และดึงหมัดกลับมาตั้งการ์ดทุกครั้งหลังออกหมัด','','uploads/cardio/videoloop/boxing_training_loop.mp4',2);
