INSERT INTO `workout_plan_template` (`wpt_id`, `wpt_image`, `wpt_name`, `wpt_description`, `wpt_days_per_week`, `wpt_difficulty`) VALUES (1,'uploads/weight_exercises/plan/fullbody_saver.jpg','Full Body','เหมาะกับใคร : มือใหม่ หรือคนงานยุ่ง\nจุดเด่น : บริหารครบทุกส่วนในวันเดียว สลับ Full Body A / B เพื่อให้กล้ามเนื้อได้รับการกระตุ้นสม่ำเสมอ',3,2),(2,'uploads/weight_exercises/plan/upper_lower.jpg','Upper / Lower','เหมาะกับใคร : คนที่ออกกำลังกายมาสักพัก\nจุดเด่น : แยกส่วนบน/ส่วนล่าง ให้กล้ามเนื้อแต่ละส่วนพัก 72 ชั่วโมง',4,2),(3,'uploads/weight_exercises/plan/hybrid_power.jpg','Body Split','เหมาะกับใคร : สายฟิตเนสที่ต้องการเพิ่ม Volume และแยกฝึกกล้ามเนื้อทีละกลุ่มแบบเจาะลึก\nจุดเด่น : แบ่งฝึกทีละกล้ามเนื้อ 5 วัน อก/หลัง/ไหล่/แขน/ขา เพิ่มปริมาณงานต่อกล้ามเนื้อในแต่ละวันได้เต็มที่',5,3),(4,'uploads/weight_exercises/plan/hardcore_ppl.jpg','Push / Pull / Legs','เหมาะกับใคร : นักกีฬาหรือคนที่ฝึกมาอย่างจริงจัง\nจุดเด่น : แบ่งกลุ่มกล้ามเนื้อตามการเคลื่อนไหว Push/Pull/Legs วนซ้ำ 2 รอบ/สัปดาห์',6,3);
/*!40000 ALTER TABLE `workout_plan_template` ENABLE KEYS */;
UNLOCK TABLES;

